// ---------------------------------------------------------------------------
// State hourly paycheck pages — per-state facts and SEO content
// ---------------------------------------------------------------------------
// Worked examples are generated by running calculatePaycheck(), so the numbers
// in the article always match what the calculator shows.

import {
  calculatePaycheck,
  type FilingStatus,
  type PayFrequency,
  type StateCode,
  TAX_YEAR,
} from './withholding-2026';

const usd = (n: number) => n.toLocaleString('en-US', { style: 'currency', currency: 'USD' });

function singleFullTime(state: StateCode, hourlyRate: number, stateAllowances = 0) {
  return calculatePaycheck({
    state,
    hourlyRate,
    regularHoursPerWeek: 40,
    overtimeHoursPerWeek: 0,
    overtimeMultiplier: 1.5,
    payFrequency: 'bi-weekly',
    filingStatus: 'single',
    stateAllowances,
  });
}

export interface StatePaycheckPage {
  code: StateCode;
  name: string;
  slug: string;
  /** Label and default for the state withholding form input; null if the state has no allowance input */
  allowances: { label: string; help: string; defaultSingle: number; defaultMarried: number } | null;
  minimumWage: number;
  minimumWageNote: string;
  overtimeRule: string;
  stateTaxSummary: string;
  extraFaqs: { question: string; answer: string }[];
  sources: string[];
}

