export const STATE_CODES = Object.keys(STATE_PAYCHECK_PAGES) as StateCode[];

const FREQ_WORD: Record<PayFrequency, string> = {
  weekly: 'weekly',
  'bi-weekly': 'every two weeks',
  'semi-monthly': 'twice a month',
  monthly: 'monthly',
};

interface Scenario {
  title: string;
  hourlyRate: number;
  regularHours: number;
  overtimeHours: number;
  filingStatus: FilingStatus;
  payFrequency: PayFrequency;
  nycResident?: boolean;
}

function describeScenario(page: StatePaycheckPage, s: Scenario) {
  const allowances = page.allowances
    ? s.filingStatus === 'married'
      ? page.allowances.defaultMarried
      : page.allowances.defaultSingle
    : 0;
  const r = calculatePaycheck({
    state: page.code,
    hourlyRate: s.hourlyRate,
    regularHoursPerWeek: s.regularHours,
    overtimeHoursPerWeek: s.overtimeHours,
    overtimeMultiplier: 1.5,
    payFrequency: s.payFrequency,
    filingStatus: s.filingStatus,
    stateAllowances: allowances,
    nycResident: s.nycResident,
  });
  const hours =
    s.overtimeHours > 0
      ? `${s.regularHours} regular hours plus ${s.overtimeHours} overtime hours a week`
      : `${s.regularHours} hours a week`;
  const status =
    s.filingStatus === 'married' ? 'married' : s.filingStatus === 'hoh' ? 'head of household' : 'single';
  const allowanceText = page.allowances ? ` and ${allowances} ${page.allowances.label}` : '';
  const lines = r.deductions.map((d) => `${d.label} ${usd(d.perPeriod)}`).join(', ');
  return {
    title: s.title,
    description:
      `${usd(s.hourlyRate)} an hour for ${hours}, paid ${FREQ_WORD[s.payFrequency]}, filing ${status}${allowanceText}. ` +
      `Gross pay is ${usd(r.grossPerPeriod)} per paycheck (${usd(r.grossAnnual)} a year). ` +
      `Withheld per paycheck: ${lines}. ` +
      `Take-home pay: ${usd(r.netPerPeriod)} per paycheck, or ${usd(r.netAnnual)} a year — about ${usd(r.netPerHour)} per hour worked.`,
  };
}

export function buildStatePaycheckSeo(code: StateCode) {
  const page = STATE_PAYCHECK_PAGES[code];
  const hasIncomeTax = page.allowances !== null || code === 'PA' || code === 'WA';

  const scenarios: Scenario[] = [
    {
      title: `Full Time at the ${page.name} Minimum Wage`,
      hourlyRate: page.minimumWage,
      regularHours: 40,
      overtimeHours: 0,
      filingStatus: 'single',
      payFrequency: 'bi-weekly',
    },
    {
      title: `$25 an Hour in ${page.name}`,
      hourlyRate: 25,
      regularHours: 40,
      overtimeHours: 0,
      filingStatus: 'single',
      payFrequency: 'bi-weekly',
    },
    {
      title: `$32 an Hour with 5 Hours of Overtime, Married`,
      hourlyRate: 32,
      regularHours: 40,
      overtimeHours: 5,
      filingStatus: 'married',
      payFrequency: 'weekly',
    },
  ];
  if (code === 'NY') {
    scenarios.splice(2, 0, {
      title: '$25 an Hour as a New York City Resident',
      hourlyRate: 25,
      regularHours: 40,
      overtimeHours: 0,
      filingStatus: 'single',
      payFrequency: 'bi-weekly',
      nycResident: true,
    });
  }

  const otherStates = STATE_CODES.filter((c) => c !== code)
    .slice(0, 6)
    .map((c) => STATE_PAYCHECK_PAGES[c]);

  return {
    howToSteps: [
      `Enter your hourly wage. The ${page.name} minimum wage for ${TAX_YEAR} is ${usd(page.minimumWage)}${code === 'NY' ? ' in New York City, Long Island, and Westchester' : ''}.`,
      'Enter your regular hours per week and any overtime hours. Overtime is paid at 1.5× your hourly rate.',
      'Choose how often you are paid (weekly, every two weeks, twice a month, or monthly) and your federal filing status from your W-4.',
      page.allowances
        ? `Enter your ${page.allowances.label}${code === 'NY' ? ' and whether you live in New York City' : ''}. Leave the default if you are not sure.`
        : `Review your instant ${page.name} and federal withholding breakdown below.`,
      'Your take-home pay per paycheck, per month, and per year updates automatically in real time.',
    ],

    formula: hasIncomeTax
      ? `Take-Home Pay = Gross Pay − Federal Income Tax − Social Security − Medicare − ${page.name} Deductions`
      : 'Take-Home Pay = Gross Pay − Federal Income Tax − Social Security − Medicare',
    formulaDescription:
      `Gross pay is your hourly rate × regular hours, plus overtime hours × rate × 1.5, converted to your pay period. ` +
      `Federal income tax is estimated with the IRS ${TAX_YEAR} percentage method for a W-4 with no extra adjustments: annual wages minus the standard deduction, taxed at the ${TAX_YEAR} brackets. ` +
      `Social Security is 6.2% of wages up to $184,500, and Medicare is 1.45% (plus 0.9% above $200,000). ` +
      page.stateTaxSummary,

    workedExamples: scenarios.map((s) => describeScenario(page, s)),

    faqs: [
      {
        question: `How much tax is taken out of a paycheck in ${page.name}?`,
        answer:
          `${page.stateTaxSummary} On top of state deductions, every worker pays federal income tax (based on your W-4), Social Security at 6.2%, and Medicare at 1.45%. ` +
          `For a single worker earning $25 an hour full time, total deductions come to about ${Math.round(
            singleFullTime(code, 25, page.allowances?.defaultSingle ?? 0).effectiveRate * 100
          )}% of gross pay.`,
      },
      {
        question: `What is the minimum wage in ${page.name} in ${TAX_YEAR}?`,
        answer: page.minimumWageNote,
      },
      {
        question: `How does overtime work in ${page.name}?`,
        answer:
          `${page.overtimeRule} Enter your weekly overtime hours in the calculator to include them. ` +
          'Under the federal "no tax on overtime" rule for 2025–2028, you may be able to deduct up to $12,500 of the extra half of your overtime pay ($25,000 if married filing jointly) on your federal return. That deduction is claimed when you file, so it does not lower the withholding shown here unless you adjust your W-4.',
      },
      ...page.extraFaqs,
      {
        question: 'How accurate is this paycheck estimate?',
        answer:
          `It uses the official ${TAX_YEAR} withholding formulas, so for a standard W-4${page.allowances ? ` and ${page.allowances.label}` : ''} with no other deductions it should be within a few dollars of your actual paycheck. ` +
          'Your real check will be lower if you have pre-tax deductions like 401(k) contributions or health insurance premiums (those also reduce your income tax), or extra withholding on your W-4. ' +
          `Sources: IRS Rev. Proc. 2025-32, Social Security Administration ${TAX_YEAR} wage base, ${page.sources.join('; ')}.`,
      },
    ],

    relatedTools: [
      {
        slug: 'hourly-paycheck-calculator',
        title: 'Hourly Paycheck Calculator',
        description: 'Quick take-home estimate for any state with 401(k) & health deductions',
        icon: 'DollarSign',
      },
      ...otherStates.map((s) => ({
        slug: s.slug,
        title: `${s.name} Hourly Paycheck Calculator`,
        description: `${TAX_YEAR} take-home pay after ${s.name} and federal taxes`,
        icon: 'Map',
      })),
      {
        slug: 'time-card-calculator',
        title: 'Time Card Calculator',
        description: 'Add up weekly hours and overtime from your clock-in times',
        icon: 'Clock',
      },
    ],
  };
}
